import React from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { useInView } from "react-intersection-observer";
import { useNavigate } from 'react-router-dom';

function Brandcat() {
  const { ref, inView } = useInView();
  const navigate = useNavigate();
  return (
    <div className="flex flex-col min-h-screen">
      {/* Header Section */}
      <div className="p-5 sm:p-8 md:p-10 lg:p-16 flex flex-col items-center text-center flex-grow">
        <div className="w-full flex items-center justify-between">
          <p className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer pl-5" onClick={() => navigate(-1)} >
            Go Back
          </p>
          <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-extrabold flex-1 text-center text-red-500">
            Branding
          </h1>
        </div>

        {/* Cinematography Container */}
        <div className="p-5 sm:p-8 md:p-10 lg:p-16 flex flex-col items-center w-full space-y-12">
          {[
            {
              title: "Simple Design- EcoSprout Branding",
              img: "Kungfu.avif",
              desc: "Branding of a start-up seeds company that sells huge variety of seeds at local convenience.",
              link: "/kungfu" // Link to Card.js
            },
            {
              title: "Redesign- Cafe Bites' Rebranding",
              img: "Delusion.avif",
              desc: "Redesigning of a local cafe in Ujjain.",
              link: "/delusion" // Link to Kalpana.js
            },
            {
              title: "Short Film - Day in life at Avantika",
              img: "Avantika.avif",
              desc: "My very first attempt at capturing a day in my life at Avantika University and turning it into something memorable using Premiere Pro.",
              link: "/avantika" // Link to CN.js
            },

          ].map((item, index) => (
            <div
              key={index}
              className="flex flex-col md:flex-row-reverse items-center w-full space-y-6 md:space-y-0 md:space-x-8"
            >
              {/* Text Section */}
              <div className="md:w-1/2 w-full flex flex-col items-center md:items-start text-center md:text-left">
                <h2 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl font-semibold">
                  {item.title}
                </h2>
                <p className="text-base sm:text-lg md:text-xl mt-4 max-w-md">
                  {item.desc}
                </p>
                <Link to={item.link} className="border border-black px-6 py-3 text-base mt-4 transition duration-300 hover:bg-black hover:text-white">
                  Read More
                </Link>
              </div>

              {/* Image Section */}
              <div className="md:w-1/2 w-full flex justify-center">
                <img
                  src={item.img}
                  className="w-11/12 sm:w-4/5 md:w-full lg:w-4/5 xl:w-3/5 h-auto rounded-lg shadow-md"
                  alt={item.title}
                />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Footer Section */}
      <div className="bg-black flex flex-col items-center justify-center text-white w-full py-20 space-y-4">
        <div className="flex flex-wrap justify-between w-full max-w-3xl items-start gap-4">
          <ul className="space-y-1">
            <li className="text-lg font-semibold">CONTACT</li>
            <li>
              <a
                href="mailto:sanskritichauhan1234@gmail.com"
                className="hover:underline"
              >
                sanskritichauhan1234@gmail.com
              </a>
            </li>
            <li>
              <a href="tel:+919867067656" className="hover:underline">
                +91 9867067656
              </a>
            </li>
          </ul>
          <nav>
            <ul className="flex flex-col items-center space-y-1">
              <Link to="/" className="text-lg hover:underline">
                HOME
              </Link>
              <Link to="/about" className="text-lg hover:underline">
                ABOUT
              </Link>
              <Link to="/portfolio" className="text-lg hover:underline">
                PORTFOLIO
              </Link>
              <Link to="/photography" className="text-lg hover:underline">
                PHOTOGRAPHY
              </Link>
            </ul>
          </nav>
        </div>

        {/* Name Display - Animated */}
        <motion.div
          ref={ref}
          className="text-center"
          initial={{ opacity: 0, y: 50 }}
          animate={inView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.8, ease: "easeOut" }}
        >
          <span className="font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">
            SANSKRITI CHAUHAN
          </span>
        </motion.div>
      </div>
    </div>
  );
}

export default Brandcat;
